package run.ikaros.photo; import java.util.UUID; import org.springframework.data.repository.reactive.ReactiveCrudRepository; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; public interface PhotoRepository extends ReactiveCrudRepository<PhotoEntity,UUID>{Flux<PhotoEntity> findAllByOwnerIdOrderByCaptureTimeDesc(UUID ownerId);Mono<PhotoEntity> findByOwnerIdAndResourceId(UUID ownerId,UUID resourceId);}
